/**
 * freq_div.v
 *
 * Frequency Divider Module - Enhanced Modular Implementation with Parameterization and Synchronous Reset
 *
 * Inputs:
 *   CLK_in - 100 MHz input clock
 *   RST    - Synchronous active-high reset
 *
 * Outputs:
 *   CLK_50 - 50 MHz clock output (CLK_in / 2)
 *   CLK_10 - 10 MHz clock output (CLK_in / 10)
 *   CLK_1  -  1 MHz clock output (CLK_in / 100)
 *
 * Each output clock is generated by a dedicated always block with its own counter,
 * toggling output signals at half the desired output period count for accurate frequency division.
 * Reset is synchronous to CLK_in for better timing and synthesis behavior.
 */

module freq_div (
    input  wire CLK_in,
    input  wire RST,      // Synchronous reset
    output reg  CLK_50,
    output reg  CLK_10,
    output reg  CLK_1
);

    // Parameters: Half-period counts (toggle intervals) for frequency division
    localparam integer DIV_50_HALF  = 1 - 1;   // 1 toggle every clock cycle (divide by 2)
    localparam integer DIV_10_HALF  = 5 - 1;   // Toggle every 5 cycles (divide by 10)
    localparam integer DIV_100_HALF = 50 - 1;  // Toggle every 50 cycles (divide by 100)

    // Counter widths (min bits to count up to max values)
    // For 5-1 = 4: needs 3 bits; for 50-1 = 49: needs 6 bits
    reg [2:0]  cnt_10;
    reg [5:0]  cnt_100;

    // CLK_50 generation: toggles every clock cycle -> divide by 2
    always @(posedge CLK_in) begin
        if (RST) begin
            CLK_50 <= 1'b0;
        end else begin
            CLK_50 <= ~CLK_50;
        end
    end

    // CLK_10 generation: toggle every 5 CLK_in cycles
    always @(posedge CLK_in) begin
        if (RST) begin
            cnt_10 <= 3'd0;
            CLK_10 <= 1'b0;
        end else if (cnt_10 == DIV_10_HALF) begin
            cnt_10 <= 3'd0;
            CLK_10 <= ~CLK_10;
        end else begin
            cnt_10 <= cnt_10 + 1'b1;
        end
    end

    // CLK_1 generation: toggle every 50 CLK_in cycles
    always @(posedge CLK_in) begin
        if (RST) begin
            cnt_100 <= 6'd0;
            CLK_1 <= 1'b0;
        end else if (cnt_100 == DIV_100_HALF) begin
            cnt_100 <= 6'd0;
            CLK_1 <= ~CLK_1;
        end else begin
            cnt_100 <= cnt_100 + 1'b1;
        end
    end

endmodule